#!/usr/bin/env bash
# Starts the Playwright MCP server that the qa agent uses (tools named mcp__playwright__*).
# Generated by vig's cloud kit; edit it in vig, not here.
#
# In a Claude Code cloud session (CLAUDE_CODE_REMOTE=true), the VM runs as root and ships
# Chrome for Testing at $CHROME_PATH, so the server runs headless, uses that Chrome, and turns
# off the Chrome sandbox (which refuses to run as root). Locally it runs with Playwright's defaults.

PLAYWRIGHT_MCP_VERSION="0.0.84"

if [ "$CLAUDE_CODE_REMOTE" = "true" ]; then
  CLOUD_CHROME="${CHROME_PATH:-/usr/bin/google-chrome}"
  exec npx -y "@playwright/mcp@${PLAYWRIGHT_MCP_VERSION}" \
    --headless \
    --no-sandbox \
    --executable-path "$CLOUD_CHROME"
fi

exec npx -y "@playwright/mcp@${PLAYWRIGHT_MCP_VERSION}"
